(function(){"use strict";function i(){const n=document.getElementById("statify-reset-data");n&&n.addEventListener("click",a=>{a.preventDefault();const t=a.currentTarget;if(t.disabled||!confirm(wp.i18n.__("Are you sure you want to delete all statistics data? This action cannot be undone!","statify")))return;const s=t.textContent;t.disabled=!0,t.textContent=wp.i18n.__("Resetting\u2026","statify"),wp.apiFetch({path:"/statify/v1/reset",method:"POST"}).then(e=>{alert(e.message)}).catch(e=>{alert(wp.i18n.__("Error:","statify")+e.message)}).finally(()=>{t.disabled=!1,t.textContent=s})})}document.addEventListener("DOMContentLoaded",i)})();
